"""CPU-authored C394300 left-turn-onto-highway and merge route proposals.

This geometry does not certify CARLA lane designation, vehicle tracking, or
actual post-turn distance. Saved Native samples determine those observables.
"""
import json
import math
from pathlib import Path
import xml.etree.ElementTree as ET

STEP_M = .1
LANE_WIDTH_M = 3.5
TURN_END_X = -66.5
TARGET_FEET = {'below_50_ft':45, 'at_50_ft':50, 'above_50_ft':55}


def open_drive():
    root = ET.Element('OpenDRIVE')
    ET.SubElement(root, 'header', revMajor='1', revMinor='4', name='C394300-after-left-turn-draft',
                  version='1', date='2026-11-05', north='100', south='-100',
                  east='100', west='-100', vendor='full-train-worker')
    # CARLA reflects OpenDRIVE y on import. Author northbound/right-curving
    # coordinates so the observed Native movement is southbound then left/east.
    roads = [(4,-73.5,-50,math.pi/2,44.75,-1),
             (13,-73.5,-5.25,math.pi/2,7*math.pi/2,100),
             (1,-66.5,1.75,0,166.5,-1)]
    for ident,x,y,heading,length,junction in roads:
        road = ET.SubElement(root,'road',id=str(ident),name=f'C394300_3c_{ident}',
                             length=str(length),junction=str(junction))
        link = ET.SubElement(road,'link')
        if ident == 4: ET.SubElement(link,'successor',elementType='junction',elementId='100')
        if ident == 13:
            ET.SubElement(link,'predecessor',elementType='road',elementId='4',contactPoint='end')
            ET.SubElement(link,'successor',elementType='road',elementId='1',contactPoint='start')
        if ident == 1: ET.SubElement(link,'predecessor',elementType='junction',elementId='100')
        geom = ET.SubElement(ET.SubElement(road,'planView'),'geometry',s='0',x=str(x),y=str(y),
                             hdg=str(heading),length=str(length))
        if ident == 13: ET.SubElement(geom,'arc',curvature=str(-1/7))
        else: ET.SubElement(geom,'line')
        ET.SubElement(ET.SubElement(road,'elevationProfile'),'elevation',s='0',a='0',b='0',c='0',d='0')
        lanes = ET.SubElement(road,'lanes')
        ET.SubElement(lanes,'laneOffset',s='0',a='0',b='0',c='0',d='0')
        section = ET.SubElement(lanes,'laneSection',s='0')
        for side, ids in (('left',(1,)),('center',(0,)),
                          ('right',(-1,) if ident==13 else (-1,-2))):
            group = ET.SubElement(section,side)
            for lane_id in ids:
                center_turn = ident==1 and lane_id==-1
                lane = ET.SubElement(group,'lane',id=str(lane_id),
                                     type='none' if lane_id==0 else 'bidirectional' if center_turn else 'driving',level='false')
                if lane_id:
                    ET.SubElement(lane,'width',sOffset='0',a=str(LANE_WIDTH_M),b='0',c='0',d='0')
                    if center_turn:
                        ET.SubElement(lane,'userData',code='lane_use',value='left_turn_only_both_directions')
                if ident==13 and lane_id==-1:
                    ll=ET.SubElement(lane,'link')
                    ET.SubElement(ll,'predecessor',id='-1');ET.SubElement(ll,'successor',id='-1')
                ET.SubElement(lane,'roadMark',sOffset='0',type='broken' if lane_id else 'solid',
                              color='yellow' if lane_id in (0,-1) else 'white',width='0.12')
        ET.SubElement(road,'objects');ET.SubElement(road,'signals')
    junction=ET.SubElement(root,'junction',id='100',name='left_onto_center_lane')
    connection=ET.SubElement(junction,'connection',id='0',incomingRoad='4',
                             connectingRoad='13',contactPoint='start')
    ET.SubElement(connection,'laneLink',**{'from':'-1','to':'-1'})
    return ET.tostring(root,encoding='unicode')


def route(case, merge_length_m=8.0, start_y_m=45.0):
    if case not in TARGET_FEET: raise ValueError('Unknown draft case')
    if not 6 <= merge_length_m <= 12: raise ValueError('Unsupported merge length')
    if start_y_m not in (42.0,45.0): raise ValueError('Unsupported inbound start')
    points=[]
    for i in range(round((start_y_m-5.1)/STEP_M)+1):
        points.append([-71.75,round(-start_y_m+i*STEP_M,5)])
    # The authored -1 lane center turns clockwise at radius 5.25 m;
    # reflection on import makes this a Native left turn.
    for i in range(1,151):
        theta=math.pi-i*(math.pi/2)/150
        points.append([round(TURN_END_X+5.25*math.cos(theta),5),
                       round(-5.25+5.25*math.sin(theta),5)])
    nominal=TARGET_FEET[case]*.3048
    # First body contact with the through lane precedes full center arrival.
    # This station is a command only; the saved Native event interval decides.
    merge_start=TURN_END_X+nominal+.19*merge_length_m
    for i in range(1,1501):
        x=TURN_END_X+i*STEP_M
        phase=max(0,min(1,(x-merge_start)/merge_length_m))
        smooth=phase*phase*(3-2*phase)
        points.append([round(x,5),round(-3.5*smooth,5)])
    return points


def check():
    root=ET.fromstring(open_drive())
    roads={int(row.attrib['id']):row for row in root.findall('road')}
    assert set(roads)=={1,4,13}
    assert roads[4].find('link/successor').attrib['elementId']=='100'
    assert roads[13].find('link/predecessor').attrib['elementId']=='4'
    assert roads[13].find('link/successor').attrib['elementId']=='1'
    assert roads[1].find('link/predecessor').attrib['elementId']=='100'
    assert [(x.attrib['from'],x.attrib['to']) for x in root.findall('junction/connection/laneLink')]==[('-1','-1')]
    bidirectional=[(int(road.attrib['id']),lane) for road in roads.values()
                   for lane in road.findall("./lanes/laneSection/right/lane[@type='bidirectional']")]
    assert [(road,int(lane.attrib['id'])) for road,lane in bidirectional]==[(1,-1)]
    assert bidirectional[0][1].find("userData[@code='lane_use']").attrib['value']=='left_turn_only_both_directions'
    # Exact rectangle-union coverage without a nonportable geometry dependency.
    pavement=((-76,-5.25,100,5.25),(-76,-50,-66.5,0))
    def covered(point):
        x,y=point
        return any(a-1e-8<=x<=c+1e-8 and b-1e-8<=y<=d+1e-8
                   for a,b,c,d in pavement)
    def segment_covered(a,b):
        cuts={0.0,1.0}
        for axis in (0,1):
            delta=b[axis]-a[axis]
            if abs(delta)>1e-12:
                for rectangle in pavement:
                    for boundary in (rectangle[axis],rectangle[axis+2]):
                        t=(boundary-a[axis])/delta
                        if 0<t<1:cuts.add(t)
        times=sorted(cuts)
        return all(covered((a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t))
                   for left,right in zip(times,times[1:])
                   for t in (left,(left+right)/2,right))
    results={}
    for case, feet in TARGET_FEET.items():
        points=route(case)
        gaps=[math.dist(a,b) for a,b in zip(points,points[1:])]
        assert max(gaps)<.15, 'Route discontinuity'
        for a,b in zip(points,points[1:]):
            assert covered(a), 'Route leaves pavement'
            angle=math.atan2(b[1]-a[1],b[0]-a[0]);c=math.cos(angle);s=math.sin(angle)
            body=[(a[0]+c*u-s*v,a[1]+s*u+c*v) for u,v in
                  ((-2.5,-1),(-2.5,1),(2.5,1),(2.5,-1))]
            assert all(segment_covered(p,body[(i+1)%4]) for i,p in enumerate(body)), \
                'Prospective body leaves pavement'
        results[case]={'nominal_commanded_after_turn_ft':feet,'route_points':len(points),
                       'maximum_sample_gap_m':round(max(gaps),5),
                       'nominal_merge_start_x_m':round(TURN_END_X+feet*.3048+.19*8,5)}
    assert len({v['nominal_merge_start_x_m'] for v in results.values()})==3
    return {'passed':True,'scope':'authored OpenDRIVE, route and body proxy only',
            'authored_bidirectional_turn_only_lane':True,
            'native_center_lane_design_verified':False,'native_connector_identity_verified':False,
            'cases':results}


if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument('--output');args=parser.parse_args()
    result=check()
    if args.output:
        output=Path(args.output);output.mkdir(parents=True,exist_ok=False)
        (output/'scene.xodr').write_text(open_drive())
        for case in TARGET_FEET:
            (output/f'route-{case}.json').write_text(json.dumps(route(case)))
        (output/'geometry-check.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result))

"""Draft saved-source measurements; no physical or legal acceptance verdict."""
import hashlib
import json
import math
import subprocess
from pathlib import Path

from measure_after_turn import measure


def _required(folder, name):
    path=Path(folder)/name
    if not path.is_file(): raise ValueError('Missing required source: '+name)
    return path


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def activation_context(folder):
    geometry=json.loads(_required(folder,'road_geometry.json').read_text())
    return {'authored_center_lane_bounds_m':geometry['center_turn_lane_native_xy_bounds_m'],
            'native_center_lane_design_verified':geometry.get('native_center_lane_design_verified') is True,
            'authored_map_sha256':geometry['authored_map_sha256']}


def distance_after_turn(folder):
    samples=_required(folder,'native_samples.jsonl')
    geometry=_required(folder,'road_geometry.json')
    return measure(samples,geometry)


def turn_merge_scope(folder):
    measured=distance_after_turn(folder)
    return {'left_turn_road_transition_frame_bracket':measured['left_turn_road_transition_frame_bracket'],
            'turn_completion_frame_bracket':measured['turn_completion_frame_bracket'],
            'merge_onset_frame_bracket':measured['merge_onset_frame_bracket'],
            'full_merge_native_frame':measured['full_merge_native_frame']}


def analysis_report(folder,contract=None):
    folder=Path(folder)
    if contract is None:
        contract={'case_id':json.loads(_required(folder,'config.json').read_text())['case_id'],
                  'requirements':[
                      {'output_key':'center_lane_activation_context','method':'activation_context',
                       'inputs':['road_geometry.json']},
                      {'output_key':'after_left_turn_distance_interval','method':'distance_after_turn',
                       'inputs':['native_samples.jsonl','road_geometry.json']},
                      {'output_key':'turn_to_merge_scope','method':'turn_merge_scope',
                       'inputs':['native_samples.jsonl','road_geometry.json']}]}
    methods={'activation_context':activation_context,
             'distance_after_turn':distance_after_turn,
             'turn_merge_scope':turn_merge_scope}
    values={}
    for row in contract['requirements']:
        inputs={name:_sha(_required(folder,name)) for name in row['inputs']}
        values[row['output_key']]={'method':row['method'],
                                   'value':methods[row['method']](folder),
                                   'sources':inputs}
    return {'format':'draft-saved-analysis-v1','case_id':contract['case_id'],
            'draft_only':True,'selected':False,'measurements':values}


def _rows(folder,name):
    return [json.loads(line) for line in _required(folder,name).read_text().splitlines() if line.strip()]


def verify_original_joins(folder,count):
    names=('trace.jsonl','capture/evidence.jsonl','video_frames.jsonl',
           'native_samples.jsonl','body_history.jsonl','capture/native/frames.jsonl')
    trace,evidence,mapping,motion,body,native_frames=(_rows(folder,name) for name in names)
    if any(len(source)!=count for source in (trace,evidence,mapping,motion,body,native_frames)):
        raise ValueError('Original trace/evidence/body/frame counts differ')
    previous_frame=-1;previous_time=-math.inf
    for index,(t,e,m,n,b,f) in enumerate(zip(trace,evidence,mapping,motion,body,native_frames)):
        frame=m.get('native_frame');time=float(m['time_s'])
        if not isinstance(frame,int) or frame<=previous_frame or time<=previous_time or m['video_frame']!=index or m.get('carla_frame')!=frame:
            raise ValueError('Original frame/time mapping invalid')
        previous_frame=frame;previous_time=time
        if any(item!=frame for item in (t.get('frame'),e.get('original_frame'),n.get('native_frame'),b.get('frame'),f.get('frame'))):
            raise ValueError('Original Native frame join differs')
        if any(abs(float(item)-time)>1e-4 for item in
               (t['time_s'],e['recording_time_s'],n['time_s'],b['time_s'])):
            raise ValueError('Original Native timestamp join differs')
        if abs(float(f['simulation_time'])-float(e['replay_simulation_time_s']))>1e-4:
            raise ValueError('Original replay simulation timestamp join differs')
        captured={(round(v[0],5),round(v[1],5)) for v in e['ego']['body_vertices_m']}
        measured={(round(v[0],5),round(v[1],5)) for v in n['native_body_xy_m']}
        historical={(round(v[0],5),round(v[1],5)) for v in b['body_vertices_m']}
        if captured!=measured or measured!=historical or len(measured)!=4:
            raise ValueError('Original full body differs from saved measurement')
    meta=json.loads(_required(folder,'capture/manifest.json').read_text())
    if not meta.get('extraction_confirmed') or meta.get('frames')!=count:
        raise ValueError('Original capture extraction incomplete')
    return {'frames':count,'first_frame':mapping[0]['native_frame'],
            'last_frame':mapping[-1]['native_frame'],
            'source_hashes':{name:_sha(Path(folder)/name) for name in names}}


def video_frames(path):
    path=Path(path)
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    result=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
        '-show_entries','stream=nb_read_frames','-of','default=noprint_wrappers=1:nokey=1',str(path)],
        text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    if result.returncode or not result.stdout.strip().isdigit():
        raise ValueError('Source video decode failed: '+path.name)
    return int(result.stdout.strip())


def capture_provenance(attempt, count):
    from worker_exchange.common import digest, within
    from worker_exchange.native_output import provenance_record
    record = provenance_record(attempt)
    seal_path = attempt/'capture-seal.json'
    if not seal_path.is_file():
        return {'source_kind':record['provenance_kind'],
                'diagnostic_fixture':record['diagnostic_fixture'],
                'native_executed':False}, False
    seal = json.loads(seal_path.read_text())
    sources = seal.get('sources')
    required = {'trace.jsonl','video_frames.jsonl','capture/evidence.jsonl',
                'native_samples.jsonl','body_history.jsonl','capture/native/frames.jsonl',
                'road_geometry.json',
                'overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv'}
    if not isinstance(sources,dict) or not required <= set(sources) or digest(sources)!=seal.get('source_digest'):
        raise ValueError('Native capture seal source inventory incomplete')
    for name, expected in sources.items():
        if _sha(within(attempt,name))!=expected:
            raise ValueError('Sealed original changed: '+name)
    marker_path=attempt/'acquisition-provenance.json'
    marker=json.loads(marker_path.read_text()) if marker_path.is_file() else {}
    codes=seal.get('encoder_exit_codes')
    cameras={'overview','approach','reference_corner','driver_reference'}
    native=(record['provenance_kind']=='native' and
            record['diagnostic_fixture'] is False and
            seal.get('format')=='worker-sealed-capture-v2' and
            seal.get('provenance_kind')=='native' and
            seal.get('diagnostic_fixture') is False and
            seal.get('frames')==count and
            seal.get('events')==['capture_finished','encoders_closed','restoration_verified'] and
            seal.get('restoration',{}).get('restored') is True and
            isinstance(codes,dict) and set(codes)==cameras and
            all(type(code) is int and code==0 for code in codes.values()) and
            marker.get('diagnostic_fixture') is not True and
            marker.get('native_executed') is not False)
    return {'source_kind':record['provenance_kind'],
            'diagnostic_fixture':record['diagnostic_fixture'],
            'native_executed':native}, native


def finalize(attempt,output):
    from worker_exchange.native_output import validate_result
    attempt=Path(attempt).resolve();output=Path(output).resolve()
    if output.exists() or (attempt/'result.json').exists():
        raise ValueError('Retain original finalization; use a fresh attempt')
    config=json.loads(_required(attempt,'config.json').read_text())
    count=config['duration_s']*config['rate_hz']
    if type(count) is not int or count<2:
        raise ValueError('Recording duration/rate invalid')
    joins=verify_original_joins(attempt,count)
    provenance,native=capture_provenance(attempt,count)
    report=analysis_report(attempt)
    relation=report['measurements']['after_left_turn_distance_interval']['value']['threshold_relation']
    scope=report['measurements']['turn_to_merge_scope']['value']
    context=report['measurements']['center_lane_activation_context']['value']
    videos=[f'{name}.mkv' for name in ('overview','approach','reference_corner','driver_reference')]
    counts={name:video_frames(attempt/name) for name in videos}
    if set(counts.values())!={count}:raise ValueError('Source camera frame count differs')
    requested={'below_50_ft':'within_50_feet','at_50_ft':'unresolved_at_50_feet',
               'above_50_ft':'exceeds_50_feet'}[config['case_suffix']]
    recording_evidence=[]
    for channel in config['recording_description']['channels']:
        name=channel['name'];ref='channels/'+name+'.jsonl';_required(attempt,ref)
        recording_evidence.append({'name':name,'unit':channel['unit'],'reference':ref})
    for item in config['recording_description']['context_inputs']:
        _required(attempt,'context.json')
        recording_evidence.append({'name':item['name'],'unit':item['unit'],'reference':'context.json'})
    measured=report['measurements']['after_left_turn_distance_interval']['value']
    result={'case_id':config['case_id'],'measured_values':measured,
      'target_checks':[{'target':'full-body after-turn center-lane distance and completed merge',
        'requested':requested,'measured':relation,
        'method':'original Native connector transition, full-body center-lane completion, through-lane contact and complete merge',
        'tolerance':'source-frame bracket; unresolved boundary is unmatched',
        'matched':relation==requested and relation!='unresolved_at_50_feet',
        'physical_cause_confirmed':False,
        'cause_evidence':['road_geometry.json','native_samples.jsonl','trace.jsonl']}],
      'setup_confirmed':native and context['native_center_lane_design_verified'],
      'behavior_attempted':native,'maneuver_completed':native and scope['full_merge_native_frame'] is not None,
      'termination_reason':'full original duration retained',
      'physical_failure_flags':['center_turn_lane_design_and_pixels_unverified']+
         (['distance_threshold_unresolved'] if relation=='unresolved_at_50_feet' else []),
      'trace_reference':'trace.jsonl','video_references':videos,
      'video_frame_map_reference':'video_frames.jsonl',
      'recording_description':config['recording_description'],
      'recording_evidence':recording_evidence,
      'realized_observables':{'after_turn_center_lane_distance':{
          'value':measured['sampled_distance_m'],'unit':'m',
          'method':'original sampled path between full-body turn completion and first through-lane body contact',
          'time_window':'turn completion to merge onset','statistic':'sampled cumulative path',
          'reference':'native_samples.jsonl','interval_m':measured['distance_interval_m'],
          'turn_completion_frame_bracket':scope['turn_completion_frame_bracket'],
          'merge_onset_frame_bracket':scope['merge_onset_frame_bracket']}},
      'provenance_kind':'native' if native else 'synthetic_local_diagnostic',
      'accepted':False,'legal_verdict_claimed':False}
    validate_result(result)
    report.update(format='c394300-3c-saved-after-turn-analysis-v1',
                  candidate_id=config['candidate_id'],original_joins=joins,
                  video_frames=counts,acquisition_provenance=provenance,
                  scope='saved original Native sources and source-video decode; physical designation and legal verdict unverified')
    output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
    (attempt/'result.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    return report


if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',required=True)
    parser.add_argument('--output',required=True);args=parser.parse_args()
    print(json.dumps(finalize(args.attempt,args.output)))

"""Read fallback triggers from retained attempt sources; never certify CARLA behavior.

The pixel audit is an independent per-frame annotation. This module verifies
its coverage and source hashes; an annotation is not a substitute for looking
at original pixels during the later GPU review.
"""
import hashlib
import json
import math
from pathlib import Path

from engineering import TRIGGERS, trigger
from measure_after_turn import measure


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _rows(path):
    if not path.is_file():
        raise ValueError('Missing original trigger source: '+path.name)
    rows=[json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    if not rows:
        raise ValueError('Empty original trigger source: '+path.name)
    return rows


def _number(value,name,low=0,high=math.inf):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value) or not low<=value<=high:
        raise ValueError('Invalid original trigger observation: '+name)
    return float(value)


def _coordinate(value,name):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError('Invalid original trigger coordinate: '+name)
    return float(value)


def evaluate(attempt,candidate):
    """Return a source-hashed measured decision for one fallback candidate."""
    if candidate not in TRIGGERS:
        raise ValueError('Unknown fallback trigger')
    folder=Path(attempt)
    samples=folder/'native_samples.jsonl'
    geometry=folder/'road_geometry.json'
    rows=_rows(samples)
    frame_ids=[row.get('native_frame') for row in rows]
    if any(type(frame) is not int for frame in frame_ids) or frame_ids!=sorted(set(frame_ids)):
        raise ValueError('Original Native frame order invalid')
    metrics={};sources={'native_samples.jsonl':_sha(samples)}
    if candidate in ('fallback1','fallback2'):
        if not geometry.is_file():
            raise ValueError('Missing original trigger source: road_geometry.json')
        g=json.loads(geometry.read_text())
        measured=measure(samples,geometry)
        completion=measured['turn_completion_frame_bracket'][1]
        premerge=measured['merge_onset_frame_bracket'][0]
        sources['road_geometry.json']=_sha(geometry)
        if candidate=='fallback1':
            inbound=g.get('inbound_road_id')
            bounds=g.get('inbound_lane_native_xy_bounds_m')
            if type(inbound) is not int or not isinstance(bounds,list) or len(bounds)!=4:
                raise ValueError('Original inbound Native lane survey missing')
            x0,y0,x1,y1=(_coordinate(v,'inbound lane bound') for v in bounds)
            if not x0<x1 or not y0<y1:
                raise ValueError('Original inbound Native lane bounds invalid')
            inbound_rows=[row for row in rows if row.get('native_road_id')==inbound and row['native_frame']<completion]
            if not inbound_rows:
                raise ValueError('Original inbound Native body samples missing')
            contained=0
            for row in inbound_rows:
                body=row.get('native_body_xy_m')
                if not isinstance(body,list) or len(body)!=4:
                    raise ValueError('Original inbound Native body missing')
                points=[tuple(_coordinate(v,'body coordinate') for v in point)
                        for point in body if isinstance(point,list) and len(point)==2]
                if len(points)!=4:
                    raise ValueError('Original inbound Native body invalid')
                contained+=all(x0<=x<=x1 and y0<=y<=y1 for x,y in points)
            completion_row=next(row for row in rows if row['native_frame']==completion)
            start=_number(inbound_rows[0].get('time_s'),'inbound start time')
            finish=_number(completion_row.get('time_s'),'turn completion time')
            if finish<=start:
                raise ValueError('Original turn time order invalid')
            metrics={'inbound_body_containment_fraction':contained/len(inbound_rows),
                     'turn_completion_time_s':finish-start,
                     'inbound_sample_count':len(inbound_rows)}
        else:
            selected=[row for row in rows if row['native_frame']<=premerge]
            errors=[]
            for row in selected:
                request=row.get('controller_request')
                if not isinstance(request,dict):
                    raise ValueError('Original controller request missing')
                errors.append(_number(request.get('route_error_m'),'route_error_m'))
            metrics={'max_premerge_route_error_m':max(errors),'premerge_sample_count':len(errors)}
    else:
        path=folder/'pixel_visibility_audit.json'
        if not path.is_file():
            raise ValueError('Missing original trigger source: pixel_visibility_audit.json')
        audit=json.loads(path.read_text())
        names=('overview','approach','reference_corner','driver_reference')
        videos=audit.get('source_video_sha256')
        if audit.get('independent_original_pixel_review') is not True or not isinstance(videos,dict) or set(videos)!=set(names):
            raise ValueError('Independent original-pixel audit incomplete')
        for name in names:
            video=folder/(name+'.mkv')
            if not video.is_file() or videos[name]!=_sha(video):
                raise ValueError('Original pixel video hash differs: '+name)
            sources[name+'.mkv']=videos[name]
        flags=audit.get('frames')
        if not isinstance(flags,list) or len(flags)!=len(rows):
            raise ValueError('Original pixel frame coverage incomplete')
        visible=0
        for row,flag in zip(rows,flags):
            if not isinstance(flag,dict) or flag.get('native_frame')!=row['native_frame'] or \
                    type(flag.get('marking_visible')) is not bool or type(flag.get('body_visible')) is not bool:
                raise ValueError('Original pixel frame annotation invalid')
            visible+=flag['marking_visible'] and flag['body_visible']
        metrics={'marking_and_body_visible_fraction':visible/len(rows),'reviewed_frame_count':len(rows)}
        sources['pixel_visibility_audit.json']=_sha(path)
    evidence={'source':TRIGGERS[candidate]['source'],**metrics}
    return {'candidate_id':candidate,'triggered':trigger(candidate,evidence),
            'metric':metrics,'source_hashes':sources,'scope':'saved original-source trigger evaluation; physical review pending'}
